sp_widget.client_script:
api.controller = function() {
  var c = this;
  c.m = {};
  c.presenter = {};
  c.attendees = {};
  c.error = '';
  c.done = false;
  c.blocked = false;

  if (c.data.blocked) {
    // Trying to edit someone else's (or a non-active) reservation
    c.error = c.data.error;
    c.blocked = true;
  } else if (c.data.edit) {
    // Update mode: pre-fill the form (the server sends times in UTC)
    var e = c.data.edit;
    c.m.agenda = e.agenda;
    c.m.room = e.room;
    c.m.dept = e.dept;
    c.m.start = new Date(e.start.replace(' ', 'T') + 'Z');
    c.m.end = new Date(e.end.replace(' ', 'T') + 'Z');
    c.presenter = e.presenter;
    c.attendees = e.attendees;
  }

  c.save = function() {
    c.error = '';
    c.done = false;
    if (!c.m.start || !c.m.end) {
      c.error = 'Please choose a start and end time.';
      return;
    }
    c.server.get({
      action: 'save',
      m: {
        editId: c.data.editId || '',   // the fix: the client sends the record id itself
        agenda: c.m.agenda,
        room: c.m.room,
        dept: c.m.dept,
        presenter: c.presenter.value,
        attendees: c.attendees.value,
        start: c.m.start.toISOString(),
        end: c.m.end.toISOString()
      }
    }).then(function(r) {
      if (r.data.error) c.error = r.data.error;
      else c.done = true;
    });
  };
};

sp_widget.script:
(function() {
  var P = gs.getCurrentScopeName();
  var me = gs.getUserID();

  // Dropdown lists
  data.rooms = [];
  data.depts = [];
  var r = new GlideRecord(P + '_meeting_room'); r.orderBy('name'); r.query();
  while (r.next()) data.rooms.push({sys_id: r.getUniqueValue(), name: r.getValue('name')});
  var d = new GlideRecord(P + '_department'); d.orderBy('name'); d.query();
  while (d.next()) data.depts.push({sys_id: d.getUniqueValue(), name: d.getValue('name')});

  // Are we updating an existing reservation?
  // $sp.getParameter only works on the first load; on Save the client sends the id.
  var editId = (input && input.m) ? (input.m.editId || '') : ($sp.getParameter('sys_id') || '');
  data.editId = '';

  if (editId) {
    var ex = new GlideRecord(P + '_scheduled_meeting');
    if (ex.get(editId) && ex.getValue('applicant') == me && ex.getValue('state') == 'scheduled') {
      data.editId = editId;
      data.edit = {
        agenda: ex.getValue('agenda'),
        room: ex.getValue('meeting_room'),
        dept: ex.getValue('department'),
        presenter: {value: ex.getValue('main_presenter'), displayValue: ex.getDisplayValue('main_presenter'), name: 'presenter'},
        attendees: {value: ex.getValue('attendees'), displayValue: ex.getDisplayValue('attendees'), name: 'attendees'},
        start: ex.getValue('start_time'),
        end: ex.getValue('end_time')
      };
    } else {
      data.error = 'You can only update your own active reservations.';
      data.blocked = true;
      return;
    }
  }

  // Save (insert or update)
  if (input && input.action == 'save') {
    var m = input.m;
    if (!m.agenda || !m.room || !m.presenter || !m.start || !m.end) {
      data.error = 'Please fill in the Agenda, Meeting Room, Main Presenter, Start and End.';
      return;
    }

    var s = new GlideDateTime();
    s.setValue(m.start.replace('T', ' ').substring(0, 19));
    var e = new GlideDateTime();
    e.setValue(m.end.replace('T', ' ').substring(0, 19));

    // Zach's rule checker. The last argument lets an update ignore its own old booking.
    var msg = new MeetingRuleChecker().check(m.room, s.getValue(), e.getValue(), data.editId);
    if (msg) { data.error = msg; return; }

    var g = new GlideRecord(P + '_scheduled_meeting');
    if (data.editId) {
      g.get(data.editId);
    } else {
      g.initialize();
      g.setValue('applicant', me);
    }
    g.setValue('agenda', m.agenda);
    g.setValue('meeting_room', m.room);
    g.setValue('main_presenter', m.presenter);
    g.setValue('attendees', m.attendees || '');
    g.setValue('department', m.dept || '');
    g.setValue('start_time', s.getValue());
    g.setValue('end_time', e.getValue());

    if (data.editId) g.update(); else g.insert();
  }
})();
